{
  "claims": [
    {
      "kind": "qualitative",
      "text": "HCA Healthcare, Inc. is one of the leading health care services companies in the United States.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526044769-0004",
          "quote": "HCA Healthcare, Inc. is one of the leading health care services companies in the United States."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The company operates general acute care, behavioral, and rehabilitation hospitals, as well as freestanding ambulatory surgery centers and endoscopy centers, with facilities located in 19 states and England.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526044769-0004",
          "quote": "At December 31, 2025, we operated 190 hospitals, comprised of 179 general acute care hospitals, seven behavioral hospitals, and four rehabilitation hospitals."
        },
        {
          "chunk_id": "HCA-000119312526044769-0004",
          "quote": "In addition, we operated 121 freestanding ambulatory surgery centers (“ASCs”) and 31 freestanding endoscopy centers."
        },
        {
          "chunk_id": "HCA-000119312526044769-0004",
          "quote": "Our facilities are located in 19 states and England."
        }
      ]
    },
    {
      "kind": "quantitative",
      "text": "Revenue increased from {{m:revenue:FY-2}} in {{p:FY-2}} to {{m:revenue:FY0}} in {{p:FY0}} and {{m:revenue:LTM}} in {{p:LTM}}, while EBITDA was {{m:ebitda:FY0}} in {{p:FY0}} and {{m:ebitda:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "The company faces competition for patients from other hospitals and health care providers, and third-party payer controls may reduce its revenues.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526044769-0013",
          "quote": "Our hospitals and other facilities face competition for patients from other hospitals and health care providers."
        },
        {
          "chunk_id": "HCA-000119312526044769-0013",
          "quote": "Third-party payer controls designed to reduce costs and other payer practices intended to decrease inpatient services, surgical procedure volumes or reimbursement for services rendered may reduce our revenues."
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "Debt / EBITDA was stable from {{p:FY-2}} through {{p:LTM}}, ending at {{m:debt_to_ebitda:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "Net leverage was also stable over the period, moving from {{m:net_leverage:FY-2}} in {{p:FY-2}} to {{m:net_leverage:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "EBITDA / interest remained stable, with coverage of {{m:interest_coverage:FY-2}} in {{p:FY-2}} and {{m:interest_coverage:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "FCF / debt was broadly stable over the period, rising to {{m:fcf_to_debt:FY0}} in {{p:FY0}} before declining to {{m:fcf_to_debt:LTM}} in {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "The stability in interest coverage reflected higher interest expense from a larger average debt balance, while the average effective interest rate on long-term debt was unchanged between {{p:FY-1}} and {{p:FY0}}.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526044769-0295",
          "quote": "The $187 million increase in interest expense was primarily due to an increase in the average debt balance."
        },
        {
          "chunk_id": "HCA-000119312526044769-0295",
          "quote": "The average effective interest rate for our long-term debt was 5.0% for both 2025 and 2024."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Liquidity coverage weakened as working capital turned negative at {{p:FY0}} and a meaningful amount of short-term commercial paper borrowings was outstanding.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526044769-0298",
          "quote": "We had negative working capital of $567 million at December 31, 2025 and positive working capital of $1.237 billion at December 31, 2024."
        },
        {
          "chunk_id": "HCA-000119312526044769-0298",
          "quote": "including $2.207 billion of outstanding commercial paper notes (short-term borrowings)."
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "The liquidity coverage ratio was {{m:liquidity_coverage:FY0}} for {{p:FY0}} and {{m:liquidity_coverage:LTM}} for {{p:LTM}}.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "For {{p:LTM}}, cash from operations was {{m:cfo:LTM}}, capital expenditure was {{m:capex:LTM}}, dividends paid were {{m:dividends:LTM}}, and short-term debt was {{m:short_term_debt:LTM}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "The senior unsecured credit facility provides $8.000 billion of revolving commitments with a five-year term.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526044769-0304",
          "quote": "provides for $8.000 billion of senior unsecured revolving credit commitments with a term of five years"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "At {{p:FY0}}, $5.779 billion was available under the senior unsecured credit facility after giving effect to letters of credit and the commercial paper reserve; $5.664 billion was available as of the subsequent reporting date.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526044769-0302",
          "quote": "$5.779 billion and $5.664 billion available"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The most recently reported availability under the senior unsecured credit facility was $3.816 billion, after giving effect to letters of credit and the commercial paper reserve, with $3.086 billion available at the preceding quarter-end.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526321077-0068",
          "quote": "$3.086 billion and $3.816 billion available"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Planned capital expenditures, excluding acquisitions, were expected to be between $5.0 billion and $5.5 billion.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526437871-0066",
          "quote": "Planned capital expenditures are expected to be between $5.0 billion and $5.5 billion"
        }
      ]
    }
  ]
}

{
  "claims": [
    {
      "kind": "quantitative",
      "text": "At {{p:FY0}}, scheduled debt maturities in years two through five were {{m:maturity_year_2:FY0}}, {{m:maturity_year_3:FY0}}, {{m:maturity_year_4:FY0}} and {{m:maturity_year_5:FY0}}, respectively.",
      "citations": []
    },
    {
      "kind": "quantitative",
      "text": "At {{p:FY0}}, debt due within 24 months was {{m:debt_due_24m:FY0}}, representing {{m:share_due_24m:FY0}} of total debt, and near-term maturity cover was {{m:near_term_maturity_cover:FY0}}.",
      "citations": []
    },
    {
      "kind": "qualitative",
      "text": "During {{p:FY0}}, the company entered into a new credit agreement that provides for $8.000 billion of senior unsecured revolving credit commitments with a term of five years and terminated its prior secured revolving and term loan facilities.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526044769-0417",
          "quote": "we entered into a new credit agreement that provides for $8.000 billion of senior unsecured revolving credit commitments with a term of five years"
        },
        {
          "chunk_id": "HCA-000119312526044769-0417",
          "quote": "We terminated our $4.500 billion senior secured asset-based revolving credit facility, our $3.500 billion senior secured revolving cash flow credit facility and our senior secured term loan facility"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "At the end of {{p:FY0}}, the company had $2.207 billion of commercial paper outstanding and no borrowings outstanding under its senior unsecured credit facility.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526044769-0418",
          "quote": "At December 31, 2025, we had $2.207 billion of commercial paper outstanding, and there were no borrowings outstanding under our senior unsecured credit facility."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "During {{p:LTM}}, the company issued $3.000 billion aggregate principal amount of senior notes and used the net proceeds to repay borrowings under the commercial paper program and for general corporate purposes.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526321077-0067",
          "quote": "During April 2026, we issued $3.000 billion aggregate principal amount of senior notes"
        },
        {
          "chunk_id": "HCA-000119312526321077-0067",
          "quote": "We used the net proceeds to repay borrowings under the commercial paper program and for general corporate purposes."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "During {{p:LTM}}, the company repaid all $1.500 billion aggregate principal amount of 5.250% senior notes and all $1.000 billion aggregate principal amount of 5.375% senior notes.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526321077-0067",
          "quote": "During May 2026, we repaid all $1.500 billion aggregate principal amount of 5.250% senior notes due 2026 and all $1.000 billion aggregate principal amount of 5.375% senior notes due 2026."
        }
      ]
    }
  ]
}

