{
  "claims": [
    {
      "kind": "qualitative",
      "text": "The company's significant indebtedness requires a portion of cash flows from operations to be dedicated to principal and interest payments, reducing cash available to fund operations, capital expenditures and future business opportunities.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526044769-0145",
          "quote": "requiring a portion of cash flows from operations to be dedicated to the payment of principal and interest on our indebtedness"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The company's significant indebtedness limits its ability to obtain additional financing for working capital, capital expenditures, share repurchases, dividends, product or service line development, debt service requirements, acquisitions and general corporate or other purposes.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526044769-0145",
          "quote": "limiting our ability to obtain additional financing for working capital, capital expenditures, share repurchases, dividends, product or service line development, debt service requirements, acquisitions and general corporate or other purposes"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "The company may need to refinance outstanding indebtedness, and its ability to do so on favorable terms, or at all, is directly affected by economic and financial conditions and by credit rating downgrades.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526044769-0147",
          "quote": "We may find it necessary or prudent to refinance our outstanding indebtedness, the terms of which refinancing may not be favorable to us."
        },
        {
          "chunk_id": "HCA-000119312526044769-0147",
          "quote": "Our ability to refinance our indebtedness on favorable terms, or at all, is directly affected by the then current global economic and financial conditions"
        },
        {
          "chunk_id": "HCA-000119312526044769-0147",
          "quote": "Downgrades in our credit ratings may also negatively affect availability of debt financing and the rates at which such financing is available."
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "A breach of the financial ratio covenant under the senior unsecured credit facility could result in a default, acceleration of amounts outstanding, and an event of default under a significant portion of other indebtedness.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526044769-0149",
          "quote": "A breach of this or any other covenant could result in a default under our senior unsecured credit facility"
        },
        {
          "chunk_id": "HCA-000119312526044769-0149",
          "quote": "upon which the lenders thereunder could elect to declare all amounts outstanding to be immediately due and payable and terminate all commitments to extend further credit"
        },
        {
          "chunk_id": "HCA-000119312526044769-0149",
          "quote": "which would also result in an event of default under a significant portion of our other outstanding indebtedness"
        }
      ]
    },
    {
      "kind": "qualitative",
      "text": "Worsening or volatile general economic conditions, including inflation, have had and may continue to have a negative impact on liquidity and the ability to repay outstanding debt, and there is no assurance that additional funds can be raised on acceptable terms.",
      "citations": [
        {
          "chunk_id": "HCA-000119312526044769-0233",
          "quote": "a negative impact on our results of operations, liquidity, ability to repay our outstanding debt and trading price of our common stock"
        },
        {
          "chunk_id": "HCA-000119312526044769-0233",
          "quote": "There can be no assurance that we will be able to raise additional funds on terms acceptable to us, if at all."
        }
      ]
    }
  ]
}

